-- Additional schema-valid recovery jobs after the unchanged attempt-read seed.
-- The verification report the completed verify jobs published.
-- Runs 1 to 3 and 6 are runner jobs of fixture-verifier; runs 4 and 5 are agent jobs a
-- researcher claimed. Run 6 was superseded before anyone claimed it.
SELECT ('00000000-0000-0000-0000-'||lpad((6000+n)::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000010','00000000-0000-0000-0000-000000002008','verify',n,state,3,performer,CASE WHEN performer='runner' THEN 'fixture-verifier' END,
'{"track":"é😀","steps":[{"name":"producer","revision":"1"},{"name":"legacy-step","revision":"r"}],"parameters":{"wide":123456789012345678901234567890,"decimal":1.25,"nested":[null,false]},"output_prefix":"jobs/é😀"}',600,'2001-02-03T04:05:06.123456Z',CASE WHEN claimed AND performer='runner' THEN '00000000-0000-0000-0000-000000000023'::uuid END,CASE WHEN claimed AND performer='agent' THEN '00000000-0000-0000-0000-000000000002'::uuid END,'historical',CASE WHEN claimed THEN 'token:é😀' END,n,CASE WHEN state='claimed' THEN sha256(convert_to('fixture-'||n,'UTF8')) END,CASE WHEN state='claimed' THEN '2099-01-01Z'::timestamptz END,CASE WHEN claimed THEN '2001-02-03T04:05:07Z'::timestamptz END,CASE WHEN claimed THEN '2099-01-01Z'::timestamptz END,CASE WHEN state IN ('completed','failed') THEN '2001-02-03T04:05:08Z'::timestamptz END,CASE WHEN state='completed' THEN '00000000-0000-0000-0000-000000003018'::uuid END,CASE WHEN state='completed' AND performer='runner' THEN '00000000-0000-0000-0000-000000007002'::uuid END,CASE WHEN state='failed' AND claimed THEN 'step' END,CASE WHEN state='failed' THEN code END,CASE WHEN state='failed' THEN 'é😀 failed' END,'[{"key":"logs/é😀","size_bytes":5,"sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}]',origin,CASE WHEN origin<>'submission' THEN '00000000-0000-0000-0000-000000006001'::uuid END
FROM (VALUES(1,'runner','completed','submission',true,NULL),(2,'runner','failed','auto_retry',true,'opaque_code'),(3,'runner','claimed','human_retry',true,NULL),(4,'agent','failed','submission',true,'opaque_code'),(5,'agent','completed','auto_retry',true,NULL),(6,'runner','failed','human_retry',false,'superseded')) AS x(n,performer,state,origin,claimed,code);
UPDATE search_documents SET updated_at='2001-01-01Z',occurred_at='2001-01-01Z';
UPDATE search_documents SET updated_at='2001-01-01Z',occurred_at='2001-01-01Z';
